content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-09-weather-care-010

=== 用户原始指令 (query.txt) ===
弄个天气关怀的卡片，点一下能跳到健康应用里，提醒说我快不行了

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "弄个天气关怀的卡片，点一下能跳到健康应用里，提醒说我快不行了",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "huaweischeme://healthapp/home/sport?sportType=2"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "当前天气查询的区县名称",
            "sampleValue": "海淀区"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本",
            "sampleValue": "36°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象",
            "sampleValue": "晴热"
          },
          "airQuality": {
            "type": "string",
            "description": "当前空气质量等级",
            "sampleValue": "良"
          },
          "uvIndex": {
            "type": "string",
            "description": "当前紫外线等级",
            "sampleValue": "强"
          },
          "coldLevel": {
            "type": "string",
            "description": "感冒指数",
            "sampleValue": "易发"
          },
          "alertLevel": {
            "type": "string",
            "description": "天气预警等级或风险提示",
            "sampleValue": "高温预警"
          }
        }
      }
    }
  },
  "assetCandidates": []
}

