 ' + ${/data/weather/current/coldLevel} }}","styles":{"width":76,"height":16,"fontSize":12,"fontWeight":500,"fontColor":"#99ffffff","maxLines":1}},{"id":"support_meta","component":"Text","content":"{{ '紫外线 ' + ${/data/weather/current/uvIndex} }}","styles":{"width":76,"height":16,"fontSize":12,"fontWeight":500,"fontColor":"#99ffffff","maxLines":1}},{"id":"action_button","component":"Button","label":"打开健康","onClick":[{"call":"clickToDeeplink","args":{"bundleName":"","abilityName":"","uri":"huaweischeme://healthapp/home/sport?sportType=2"}}],"styles":{"width":92,"height":34,"borderRadius":17,"backgroundColor":"#FFFFFFFF","fontSize":14,"fontWeight":500,"fontColor":"#e5000000"}}]}}
